<?php
/** Proof — credit notes, write-offs, the statement and reminders (spec "Proof", 6–7). */
require __DIR__ . '/lib.php';
$bea = as_member(27); $carl = as_member(28); $vera = as_member(26);
$fx = ar_fixture();
$C = mk_customer('SMOKE Credit Customer');
echo "1. A credit note\n";
$inv = mk_invoice($C, [['Service', '1', '100.00'], ['Goods', '1', '200.00', (string) $fx['tax'], '4000']], ['issue_date' => '2026-06-01']); issue($inv);
$ir = inv_row($inv);
ok($ir['total'] === '316.50' && $ir['balance_due'] === '316.50', 'the invoice: 300.00 + 16.50 tax = 316.50');
$body = page($bea, '/credit-notes/new?customer=' . $C . '&invoice=' . $inv)['body'];
ok(str_contains($body, 'id="credit-note-form-against"') && str_contains($body, 'value="Service"') && str_contains($body, 'value="Goods"'), 'the Credit button\'s form is prefilled with the invoice\'s lines');
$since = last_activity_id();
[$c, $b] = act($bea, '/credit-notes/save.php', ['customer' => $C, 'invoice' => $inv, 'issue_date' => '2026-06-10', 'reason' => 'SMOKE goodwill', 'lines' => json_encode([['description' => 'Goodwill', 'quantity' => '1', 'unit_price' => '100.00', 'income_account' => '4100', 'tax_rate' => '']])]);
$cn = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $cn > 0 && ($b['location'] ?? '') === '/credit-notes/' . $cn . '?notice=saved', "credit_note_draft: 200, record_id $cn");
$row = q('SELECT * FROM credit_notes WHERE id = :c', ['c' => $cn])[0];
ok($row['status'] === 'draft' && $row['number'] === null && $row['total'] === '100.00' && (int) $row['invoice_id'] === $inv && $row['currency'] === 'USD', 'a draft against the invoice, 100.00');
ok(count(activity('credit_note.draft', $since)) === 1, 'credit_note.draft logged');
[$c, $b] = act($bea, '/credit-notes/line-save.php', ['credit_note' => $cn, 'description' => 'Extra', 'quantity' => '1', 'unit_price' => '25.00', 'income_account' => '4100']);
$ln = (int) $b['record_id'];
ok($c === 200 && (string) one('SELECT total FROM credit_notes WHERE id = :c', ['c' => $cn]) === '125.00', 'a second line: the total follows (125.00)');
[$c, $b] = act($bea, '/credit-notes/line-remove.php', ['credit_note' => $cn, 'line' => $ln]);
ok($c === 200 && (string) one('SELECT total FROM credit_notes WHERE id = :c', ['c' => $cn]) === '100.00', 'removed: back to 100.00');
$r = req('POST', '/credit-notes/line-save.php', ['jar' => $bea, 'headers' => ['HX-Request: true', 'HX-Target: credit-note-lines'], 'form' => ['credit_note' => $cn, 'description' => 'Htmx', 'quantity' => '1', 'unit_price' => '1', 'income_account' => '4100', 'csrf_token' => csrf_of(page($bea, '/')['body'])]]);
ok($r['code'] === 200 && str_starts_with(trim($r['body']), '<div id="credit-note-lines"') && str_contains($r['body'], 'id="credit-note-totals" hx-swap-oob="true"'), 'under HTMX a line write re-renders #credit-note-lines with the totals out of band');
act($bea, '/credit-notes/line-remove.php', ['credit_note' => $cn, 'line' => (int) one('SELECT max(id) FROM credit_note_lines WHERE credit_note_id = :c', ['c' => $cn])]);
$since = last_activity_id();
[$c, $b] = act($bea, '/credit-notes/issue.php', ['credit_note' => $cn, 'apply_to' => $inv]);
ok($c === 200 && preg_match('/^CN-\d{5}$/', (string) one('SELECT number FROM credit_notes WHERE id = :c', ['c' => $cn])) === 1, 'credit_note_issue: numbered CN-…');
$row = q('SELECT * FROM credit_notes WHERE id = :c', ['c' => $cn])[0];
$jl = array_column(q('SELECT a.code, l.debit, l.credit FROM journal_lines l JOIN accounts a ON a.id = l.account_id WHERE l.entry_id = :e', ['e' => $row['journal_entry_id']]), null, 'code');
ok($row['status'] === 'issued' && $row['amount_applied'] === '100.00' && $row['balance'] === '0.00' && $jl['4100']['debit'] === '100.00' && $jl['1200']['credit'] === '100.00', 'issued and applied at once: DR 4100 100.00 / CR 1200 100.00');
$x = inv_row($inv);
ok($x['amount_credited'] === '100.00' && $x['status'] === 'partially_paid' && $x['balance_due'] === '216.50', 'the invoice: credited 100.00, partially paid, 216.50 due');
$l = activity('credit_note.issue', $since)[0]; $a = json_decode((string) $l['after'], true);
ok($a['amount'] === '100.00' && $a['currency'] === 'USD' && str_starts_with($a['journal_entry_number'], 'JE-') && (int) $l['customer_id'] === $C && count(activity('credit_note.apply', $since)) === 1, 'credit_note.issue logs the amount, currency, entry number; credit_note.apply too');
[$c, $b] = act($carl, '/credit-notes/void.php', ['credit_note' => $cn, 'reason' => 'SMOKE x']);
ok($c === 422 && str_contains(msg($b), 'is applied to an invoice; unapply it first'), 'void refused while applied: "… unapply it first"');
[$c, $b] = act($bea, '/credit-notes/unapply.php', ['credit_note' => $cn, 'invoice' => $inv]);
ok($c === 200 && inv_row($inv)['amount_credited'] === '0.00' && inv_row($inv)['balance_due'] === '316.50', 'unapply: the invoice owes 316.50 again');
[$c, $b] = act($bea, '/credit-notes/apply.php', ['credit_note' => $cn, 'invoice' => $inv, 'amount' => '150']);
ok($c === 422 && str_contains(msg($b), 'would exceed it'), 'applying more than the credit: 422 in the guard\'s words');
[$c, $b] = act($bea, '/credit-notes/apply.php', ['credit_note' => $cn, 'invoice' => $inv, 'amount' => '40']);
ok($c === 200 && inv_row($inv)['amount_credited'] === '40.00', 'a partial application (40.00)');
act($bea, '/credit-notes/unapply.php', ['credit_note' => $cn, 'invoice' => $inv]);
$since = last_activity_id();
[$c, $b] = act($carl, '/credit-notes/void.php', ['credit_note' => $cn, 'reason' => 'SMOKE issued in error']);
ok($c === 200 && (string) one('SELECT status FROM credit_notes WHERE id = :c', ['c' => $cn]) === 'void' && (int) one('SELECT count(*) FROM journal_entries WHERE reversal_of = :e', ['e' => $row['journal_entry_id']]) === 1 && count(activity('credit_note.void', $since)) === 1, 'unapplied, a credit note is voided by the Controller: its entry reversed, logged');
[$c, $b] = act($bea, '/credit-notes/void.php', ['credit_note' => (int) one("SELECT max(id) FROM credit_notes WHERE customer_id = :c", ['c' => $C]), 'reason' => 'x']);
ok($c === 403, 'a Bookkeeper may not void');
$cn2 = (int) act($bea, '/credit-notes/save.php', ['customer' => $C, 'lines' => json_encode([['description' => 'Draft to delete', 'quantity' => '1', 'unit_price' => '5.00', 'income_account' => '4100']])])[1]['record_id'];
$since = last_activity_id();
[$c, $b] = act($bea, '/credit-notes/delete.php', ['credit_note' => $cn2]);
ok($c === 200 && one('SELECT 1 FROM credit_notes WHERE id = :c', ['c' => $cn2]) === false && count(activity('credit_note.delete', $since)) === 1, 'credit_note_delete removes a draft; logged');
echo "2. Write off, and the statement\n";
$w = mk_invoice($C, [['To be written off', '1', '80.00']], ['issue_date' => '2026-06-02']); issue($w);
[$c, $b] = act($bea, '/invoices/write-off.php', ['invoice' => $w, 'reason' => 'SMOKE uncollectable']);
ok($c === 403 && msg($b) === 'You may not reverse, void or write off.', 'a Bookkeeper writing off: 403 in the right\'s sentence');
[$c, $b] = act($carl, '/invoices/write-off.php', ['invoice' => $w, 'reason' => '']);
ok($c === 422 && msg($b) === 'A write-off needs a reason', 'a write-off needs a reason');
$since = last_activity_id();
[$c, $b] = act($carl, '/invoices/write-off.php', ['invoice' => $w, 'reason' => 'SMOKE uncollectable', 'write_off_date' => '2026-09-30']);
$wr = inv_row($w);
$jl = array_column(q('SELECT a.code, l.debit, l.credit FROM journal_lines l JOIN accounts a ON a.id = l.account_id WHERE l.entry_id = :e', ['e' => $wr['write_off_entry_id']]), null, 'code');
ok($c === 200 && $wr['status'] === 'written_off' && $jl['6600']['debit'] === '80.00' && $jl['1200']['credit'] === '80.00', 'invoice_write_off: DR 6600 / CR 1200 for 80.00, status written_off');
$l = activity('invoice.write_off', $since)[0]; $a = json_decode((string) $l['after'], true);
ok($a['amount'] === '80.00' && $a['currency'] === 'USD' && str_contains((string) $l['after'], 'uncollectable') && (int) $l['journal_entry_id'] === (int) $wr['write_off_entry_id'], 'invoice.write_off logs the reason, amount, currency and the entry');
[$c, $b] = act($bea, '/receipts/save.php', ['customer' => $C, 'amount' => '316.50', 'method' => 'transfer', 'invoice' => $inv]);
ok($c === 200 && inv_row($inv)['status'] === 'paid', 'the other invoice is paid in full by a receipt');
$r = req('GET', '/customers/' . $C . '/statement?from=2026-01-01&to=2026-12-31', ['jar' => $bea, 'headers' => ['Accept: application/json']]);
$s = json_decode($r['body'], true)['data']['statement'] ?? [];
ok(($s['closing'] ?? '') === '0.00' && ($s['opening'] ?? '') === '0.00', 'the statement\'s running balance ends at zero (invoices, the credit, the receipt and the write-off): ' . ($s['closing'] ?? '?'));
ok(in_array('write_off', array_column($s['rows'] ?? [], 'kind'), true), 'and shows the write-off as a line');
$since = last_activity_id();
$r = req('POST', '/customers/statement-send.php', ['jar' => $bea, 'headers' => ['Accept: application/json'], 'form' => ['customer' => $C, 'from' => '2026-01-01', 'to' => '2026-12-31', 'csrf_token' => csrf_of(page($bea, '/')['body'])]]);
$j = json_decode($r['body'], true);
$mail = q("SELECT * FROM notification_outbox WHERE id = :i", ['i' => $j['outbox_id'] ?? 0])[0] ?? null;
ok($r['code'] === 200 && $mail !== null && $mail['kind'] === 'statement' && $mail['status'] === 'queued' && str_contains($mail['body'], 'Closing balance') && count(activity('statement.send', $since)) === 1 && !str_contains((string) activity('statement.send', $since)[0]['after'], '@'), 'statement_send queues the statement for the customer; statement.send logs no address');
echo "3. Reminders\n";
$ok1 = mk_invoice($C, [['Not due yet', '1', '10.00']], ['issue_date' => date('Y-m-d'), 'due_date' => date('Y-m-d', strtotime('+10 days'))]); issue($ok1);
[$c, $b] = act($bea, '/invoices/remind.php', ['invoice' => $ok1]);
ok($c === 422 && str_contains(msg($b), 'is not past due'), 'a current invoice: 422 "… is not past due"');
$steps = [];
foreach ([[7, 1], [25, 2], [96, 3]] as [$days, $step]) {
    $due = date('Y-m-d', strtotime("-$days days"));
    $i = mk_invoice($C, [['Late ' . $days, '1', '10.00']], ['issue_date' => '2026-06-01', 'due_date' => $due]); issue($i);
    $since = last_activity_id();
    [$c, $b] = act($bea, '/invoices/remind.php', ['invoice' => $i]);
    $row = inv_row($i);
    $mail = q("SELECT * FROM notification_outbox WHERE record_type = 'invoice' AND record_id = :i AND kind = 'invoice_reminder' ORDER BY id DESC LIMIT 1", ['i' => $i])[0] ?? null;
    $steps[$step] = ['code' => $c, 'subject' => $mail['subject'] ?? '', 'count' => (int) $row['reminder_count'], 'last' => $row['last_reminder_at'], 'log' => count(activity('invoice.remind', $since))];
}
ok($steps[1]['code'] === 200 && $steps[1]['count'] === 1 && $steps[1]['last'] !== null && str_contains($steps[1]['subject'], 'A friendly reminder') && $steps[1]['log'] === 1, 'overdue by 7 days: step 1 wording ("A friendly reminder"), reminder_count 1, last_reminder_at set');
ok(str_contains($steps[2]['subject'], '25 days past due') && !str_contains($steps[2]['subject'], 'Final'), 'by 25 days: step 2, firmer');
ok(str_starts_with($steps[3]['subject'], 'Final notice') && str_contains($steps[3]['subject'], '96 days'), 'by 96 days: step 3, the final notice');
[$c, $b] = act($bea, '/invoices/remind.php', ['invoice' => $i]);
ok($c === 200 && (int) inv_row($i)['reminder_count'] === 2, 'a second reminder counts 2');
$body = page($bea, '/invoices/' . $i)['body'];
ok(str_contains($body, 'id="invoice-remind-btn"') && str_contains($body, '2 reminders'), 'the invoice page offers Remind and counts them');
echo "4. The pages\n";
[$c, $d] = screen($vera, '/credit-notes/');
ok($c === 200 && count($d['credit_notes']) >= 1, 'the credit notes list (a Viewer reads it)');
$body = page($bea, '/credit-notes/' . $cn)['body'];
ok(str_contains($body, 'id="credit-note-head-status"') && str_contains($body, 'id="credit-note-head-entry-link"') && str_contains($body, 'id="credit-note-head-void"'), 'the credit note page: status, entry link, the void reason');
ok(page($bea, '/credit-notes/424242')['code'] === 404, 'an unknown credit note: 404');
finish();
